<template>
    <template v-if="inline">
        <slot></slot>
    </template>
    <template v-else-if="mounted">
        <Teleport :to="appendTo">
            <component v-if="tracker" :is="content" />
            <slot v-else></slot>
        </Teleport>
    </template>
</template>

<script>
import { isClient } from '@primeuix/utils/dom';

export default {
    name: 'Portal',
    props: {
        appendTo: {
            type: [String, Object],
            default: 'body'
        },
        disabled: {
            type: Boolean,
            default: false
        }
    },
    data() {
        return {
            mounted: false
        };
    },
    watch: {
        appendTo() {
            this.tracker?.retarget();
            this.attachRoot();
        },
        disabled() {
            this.attachRoot();
        }
    },
    created() {
        this.tracker = this.$primevue?.isolation?.portal(() => this.target);
        this.content = () => this.tracker.content(this.$slots);
    },
    mounted() {
        this.mounted = isClient();

        this.attachRoot();
    },
    beforeUnmount() {
        this.$primevue?.shadowRoot?.detach(this);
    },
    unmounted() {
        this.tracker?.dispose();
    },
    methods: {
        attachRoot() {
            if (this.mounted && !this.tracker) this.$primevue?.shadowRoot?.attach(this, this.inline ? null : this.target);
        }
    },
    computed: {
        inline() {
            return this.disabled || this.appendTo === 'self';
        },
        target() {
            return typeof this.appendTo === 'string' ? document.querySelector(this.appendTo) : this.appendTo;
        }
    }
};
</script>
